const paid = rows.filter(r => !free(r));
const freeRows = rows.length - paid.length;
const ai = +(n0(EST.ai) * paid.length).toFixed(4);
const dfs = +paid.reduce((s, r) => s + (full(r) ? n0(EST.dfs_full) : n0(EST.dfs)), 0).toFixed(4);
